      'seed.Strength & Agility': 'Styrke & Agility',
      'seed.Goalkeeper Mobility Routine': 'Målmands-mobility',
      'seed.Interval Sprint Run': 'Intervalløb',
      'seed.Quick Feet Program': 'Hurtige ben',
      'seed.Asymmetric Single-Leg Squat with Kettlebell': 'Asymmetrisk enkeltbens-squat med kettlebell',
      'seed.Lateral Squat': 'Sidebevægelses-squat',
      'seed.Lateral Band Sidewalk': 'Sideværts gang med elastik',
      'seed.Lateral Jumps with Medicine Ball': 'Sideværts hop med medicinbold',
      'seed.Explosive Step-Up to Jump with Knee Drive': 'Eksplosivt step-up til hop med knæløft',
      'seed.Explosive Step-Up to Overhead Grab': 'Eksplosivt step-up til stang-greb',
      'seed.Handball Jumping': 'Håndboldspring',
      'seed.Bulgarian Split Squat': 'Bulgarsk split squat',
